<div class="gamification-admin-head"><h2><?php echo $this->lang('Teams') ?></h2><?php echo $this->button_create('admin/teams/add', (string)$this->lang('Create team')) ?></div>
<div class="table-responsive"><table class="table"><thead><tr><th><?php echo $this->lang('Team') ?></th><th><?php echo $this->lang('Members') ?></th><th><?php echo $this->lang('Status') ?></th><th><?php echo $this->lang('Actions') ?></th></tr></thead><tbody>
